package com.starlight.greetings.domain.moderation;
import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.Test;
class ContentModeratorTest { private final ContentModerator moderator = new ContentModerator(); @Test void classifiesBaseModerationCases(){assertEquals("profanity",moderator.category("씨발"));assertEquals("personal_info",moderator.category("010-1234-5678"));assertEquals("advertising",moderator.category("https://example.com"));assertNull(moderator.category("오늘도 잘 버텼어요."));}@Test void blocksObfuscatedPersonalInformationAndPromotion(){assertEquals("personal_info",moderator.category("연락처는 010 1234 5678 이에요"));assertEquals("personal_info",moderator.category("메일은 hello\u200B@example.com 입니다"));assertEquals("advertising",moderator.category("지금 구매하세요 특별 할인 광고입니다"));assertEquals("advertising",moderator.category("w w w . example . com 에서 확인하세요"));}
 @Test void blocksSpacedOrSymbolSeparatedProfanityAndNumbers(){assertEquals("profanity",moderator.category("씨 발 진짜"));assertEquals("profanity",moderator.category("병.신"));assertEquals("profanity",moderator.category("ㅅ1ㅂ"));assertEquals("personal_info",moderator.category("번호는 010.1234.5678이에요"));assertEquals("advertising",moderator.category("광고.문의 주세요"));}
 @Test void keepsOrdinaryLettersThatOnlyLookCloseAcrossWords(){assertNull(moderator.category("다시 발견한 마음, 솜씨 발휘한 하루였어요."));assertNull(moderator.category("병 신경 쓰지 말고 푹 쉬어요."));assertNull(moderator.category("2층 3호에 사는 이웃이 인사해 줬어요."));}}
